import{_ as t,o as a,c as e,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-03","description":"","frontmatter":{"date":"2026-07-03T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-03-uxtrend.md","filePath":"daily/2026-07-03-uxtrend.md"}'),o={name:"daily/2026-07-03-uxtrend.md"};function s(i,r,g,p,h,l){return a(),e("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-07-03" tabindex="-1">设计趋势 - 2026-07-03 <a class="header-anchor" href="#设计趋势-2026-07-03" aria-label="Permalink to &quot;设计趋势 - 2026-07-03&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势领域聚焦于代理式用户体验（UX）和AI在设计工作流程中的应用。主要动态包括：1) 面向代理的UX设计原则，旨在提升数字设备中的新型用户体验；2) 代理式UX设计的核心在于人机间的信任协调；3) AI工具加速设计工作流程，提升协作与灵活性；4) AI代理工作流设计模式的分类与实例分析；5) 设计智能代理系统时需确保上下文双向流动以增强信任。最值得关注的是代理式UX设计原则和AI工具对设计工作流程的影响。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 设计原则助力数字设备中的新型用户体验</p><p><strong>能解决什么问题</strong>: 如何以人为中心设计与数字代理系统交互的体验</p><p><strong>产品应用</strong>: 适用于产品开发，以AI为中心构建用户体验</p><p><strong>示例场景</strong>: 智能助手协助用户完成日常任务和决策</p><hr><h3 id="_2-为什么代理式ux将改变你对设计的了解" tabindex="-1">2. 为什么代理式UX将改变你对设计的了解 <a class="header-anchor" href="#_2-为什么代理式ux将改变你对设计的了解" aria-label="Permalink to &quot;2. 为什么代理式UX将改变你对设计的了解&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理式UX设计关乎于人机间的信任协调。</p><p><strong>能解决什么问题</strong>: 如何让用户信任并有效利用AI代理。</p><p><strong>产品应用</strong>: 适用于需要人机协作的智能系统，通过设计确保用户感到被支持且控制权在手。</p><p><strong>示例场景</strong>: 金融代理提示可疑交易，但需人工审批冻结账户。</p><hr><h3 id="_3-ai如何改变我的设计工作流程" tabindex="-1">3. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_3-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;3. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI工具让设计工作流程更快速、协作且灵活。</p><p><strong>能解决什么问题</strong>: 提高设计效率，减少从概念到原型的时间和成本。</p><p><strong>产品应用</strong>: 适用于产品原型设计，通过Figma和Cursor快速迭代。</p><p><strong>示例场景</strong>: 设计师使用Figma和Cursor创建交互式原型。</p><hr><h3 id="_4-ai代理工作流设计模式概览" tabindex="-1">4. AI代理工作流设计模式概览 <a class="header-anchor" href="#_4-ai代理工作流设计模式概览" aria-label="Permalink to &quot;4. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理，执行任务。</p><p><strong>产品应用</strong>: 可以应用于开发智能代理产品，通过工作流模式灵活处理问题。</p><p><strong>示例场景</strong>: 智能客服代理通过工作流模式处理客户咨询。</p><hr><h3 id="_5-代理式用户体验-设计智能代理系统的7个原则" tabindex="-1">5. 代理式用户体验：设计智能代理系统的7个原则 <a class="header-anchor" href="#_5-代理式用户体验-设计智能代理系统的7个原则" aria-label="Permalink to &quot;5. 代理式用户体验：设计智能代理系统的7个原则&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/agentic-ux-7-principles-for-designing-systems-with-agents-019512c2caa9" target="_blank" rel="noreferrer">Agentic UX: 7 principles for designing systems with agents</a></p><p><strong>一句话摘要</strong>: 设计智能代理系统时，需确保上下文双向流动以增强信任感。</p><p><strong>能解决什么问题</strong>: 解决智能代理在用户体验中的信任度和上下文连贯性问题。</p><p><strong>产品应用</strong>: 适用于需要智能代理辅助的软件产品，通过整合上下文信息提升用户体验。</p><p><strong>示例场景</strong>: 智能客服系统在用户界面中直接提供帮助，无需跳转。</p><hr><h3 id="_6-ai在设计中的应用-改变我们的创造方式" tabindex="-1">6. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_6-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;6. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create - Figma</a></p><p><strong>一句话摘要</strong>: AI正深入设计领域，提升工作效率和个性化体验。</p><p><strong>能解决什么问题</strong>: 解决设计过程中耗时耗力的任务自动化和个性化需求响应。</p><p><strong>产品应用</strong>: 可应用于产品设计，通过AI提升设计效率和用户界面个性化。</p><p><strong>示例场景</strong>: 使用AI设计工具快速生成多种界面布局方案。</p><hr><h3 id="_7-ai交互模式-让用户识别并互动ai驱动功能" tabindex="-1">7. AI交互模式：让用户识别并互动AI驱动功能 <a class="header-anchor" href="#_7-ai交互模式-让用户识别并互动ai驱动功能" aria-label="Permalink to &quot;7. AI交互模式：让用户识别并互动AI驱动功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI的信任关系。</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI功能。</p><p><strong>产品应用</strong>: 适用于AI工具，如聊天机器人、分析仪表板等。</p><p><strong>示例场景</strong>: 聊天机器人提供个性化客户服务。</p><hr><h3 id="_8-ai-ux设计模式-人工智能带来的新交互" tabindex="-1">8. AI UX设计模式：人工智能带来的新交互 <a class="header-anchor" href="#_8-ai-ux设计模式-人工智能带来的新交互" aria-label="Permalink to &quot;8. AI UX设计模式：人工智能带来的新交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://lukelance.medium.com/ai-ux-design-patterns-53d9e378f808" target="_blank" rel="noreferrer">AI UX Design Patterns. Artificial Intelligence brings a new… | by Luke Bennis | Medium</a></p><p><strong>一句话摘要</strong>: AI UX设计模式旨在帮助设计师规划包含AI的产品设计。</p><p><strong>能解决什么问题</strong>: 解决如何将AI技术有效融入用户体验设计的问题。</p><p><strong>产品应用</strong>: 适用于实际产品设计，通过评估和选择适合的AI UX模式。</p><p><strong>示例场景</strong>: 设计一个使用AI辅助的智能客服系统。</p><hr><h3 id="_9-为代理型用户体验设计指南" tabindex="-1">9. 为代理型用户体验设计指南 <a class="header-anchor" href="#_9-为代理型用户体验设计指南" aria-label="Permalink to &quot;9. 为代理型用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 设计代理型用户体验，关注未来可能存在的用户需求。</p><p><strong>能解决什么问题</strong>: 解决用户在数字环境中快速完成任务的同时，预测并满足未知需求。</p><p><strong>产品应用</strong>: 可以应用到智能助手、推荐系统等产品中，通过感知、思考、行动循环来实现。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动推荐可能感兴趣的内容。</p><hr><h3 id="_10-2026年chatgpt八大新功能-位置共享、智能附件等" tabindex="-1">10. 2026年ChatGPT八大新功能：位置共享、智能附件等 <a class="header-anchor" href="#_10-2026年chatgpt八大新功能-位置共享、智能附件等" aria-label="Permalink to &quot;10. 2026年ChatGPT八大新功能：位置共享、智能附件等&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@christianaistudio/8-chatgpt-updates-you-should-actually-know-about-and-how-to-use-them-b5d6c2018e79" target="_blank" rel="noreferrer">8 New ChatGPT’s Features: Location Sharing, Smart Attachments &amp; More (2026 Guide)</a></p><p><strong>一句话摘要</strong>: ChatGPT新增多项功能，提升用户体验。</p><p><strong>能解决什么问题</strong>: 解决用户在购物、编程、移动应用和车载系统上的交互问题。</p><p><strong>产品应用</strong>: 适用于需要自然语言处理和智能助手的各类应用场景。</p><p><strong>示例场景</strong>: 在车内通过CarPlay使用ChatGPT进行语音交互。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
